/**
 * frontend/src/components/App.jsx - APPLICATION PRINCIPALE
 * Navigation + Auth + Recherche + Notifications + UI responsive
 */

import React, { useState, useEffect, useRef } from 'react';
import Login from './pages/Login';
import Dashboard from './Dashboard';
import Enrollment from './Enrollment';
import CameraRecognition from './CameraRecognition';
import authService from './auth_service';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  error: '#EF4444',
  info: '#64748B',
  background: '#F8FAFC',
  surface: '#FFFFFF',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  sidebar: '#1E293B'
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [currentView, setCurrentView] = useState('dashboard');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);
  const [searchLoading, setSearchLoading] = useState(false);

  const [sidebarOpen, setSidebarOpen] = useState(true);

  const debounceRef = useRef(null);

  /**
   * AUTH INIT
   */
  useEffect(() => {
    try {
      authService.initialize();

      const user = authService.getUser();

      if (authService.isAuthenticated() && user) {
        setCurrentUser(user);
        setIsAuthenticated(true);
      } else {
        setCurrentUser(null);
        setIsAuthenticated(false);
      }
    } catch (err) {
      console.error('Auth init error:', err);
      setCurrentUser(null);
      setIsAuthenticated(false);
    } finally {
      setLoading(false);
    }
  }, []);

  /**
   * NOTIFICATIONS
   */
  const addNotification = (message, type = 'info') => {
    const id = Date.now();

    setNotifications((prev) => [...prev, { id, message, type }]);

    setTimeout(() => {
      setNotifications((prev) => prev.filter((n) => n.id !== id));
    }, 3500);
  };

  /**
   * CLEAN STATE ON LOGOUT
   */
  const resetAppState = () => {
    setSearchQuery('');
    setSearchResults([]);
    setShowResults(false);
    setNotifications([]);
    setCurrentView('dashboard');
  };

  /**
   * SEARCH STUDENTS
   */
  const handleSearch = (value) => {
    setSearchQuery(value);

    if (debounceRef.current) clearTimeout(debounceRef.current);

    if (!value || value.trim().length < 2) {
      setSearchResults([]);
      setShowResults(false);
      setSearchLoading(false);
      return;
    }

    setSearchLoading(true);

    debounceRef.current = setTimeout(async () => {
      try {
        const result = await studentsAPI.search(value);

        if (result.success) {
          const list = result.data?.results || [];
          setSearchResults(list);
          setShowResults(true);
        } else {
          setSearchResults([]);
          setShowResults(false);
          addNotification('Erreur lors de la recherche', 'error');
        }
      } catch (err) {
        console.error(err);
        setSearchResults([]);
        setShowResults(false);
        addNotification('Erreur de recherche', 'error');
      } finally {
        setSearchLoading(false);
      }
    }, 350);
  };

  /**
   * SELECT STUDENT
   */
  const handleSelectStudent = (student) => {
    if (!student) return;

    const name = student.name || 'Inconnu';
    setSearchQuery(name);
    setShowResults(false);

    addNotification(`Étudiant sélectionné : ${name}`, 'info');
  };

  /**
   * LOGIN SUCCESS
   */
  const handleLoginSuccess = (user) => {
    if (!user) return;

    setCurrentUser(user);
    setIsAuthenticated(true);

    addNotification(
      `Bienvenue ${user.first_name || user.username || 'Utilisateur'}`,
      'success'
    );
  };

  /**
   * LOGOUT
   */
  const handleLogout = async () => {
    try {
      await authService.logout();
    } catch (err) {
      console.error('Logout error:', err);
    }

    setCurrentUser(null);
    setIsAuthenticated(false);

    resetAppState();

    addNotification('Déconnexion réussie', 'info');
  };

  /**
   * LOADING SCREEN
   */
  if (loading) {
    return <div style={styles.loading}>Chargement...</div>;
  }

  /**
   * LOGIN GATE
   */
  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  const role =
    currentUser?.role ||
    (currentUser?.is_superuser ? 'Administrateur' : 'Utilisateur');

  const username = currentUser?.first_name || currentUser?.username || 'Utilisateur inconnu';

  return (
    <div style={styles.appWrapper}>
      {/* SIDEBAR */}
      {sidebarOpen && (
        <aside style={styles.sidebar}>
          <div style={styles.brand}>
            <div style={styles.brandIcon}>Σ</div>
            <h2 style={styles.brandName}>Attendance OS</h2>
          </div>

          <nav style={styles.sideNav}>
            <NavItem
              icon="📊"
              label="Dashboard"
              active={currentView === 'dashboard'}
              aria="dashboard"
              onClick={() => setCurrentView('dashboard')}
            />
            <NavItem
              icon="➕"
              label="Enrôlement"
              active={currentView === 'enrollment'}
              aria="enrollment"
              onClick={() => setCurrentView('enrollment')}
            />
            <NavItem
              icon="📷"
              label="Reconnaissance"
              active={currentView === 'camera'}
              aria="camera"
              onClick={() => setCurrentView('camera')}
            />
          </nav>

          <div style={styles.userInfo}>
            <div style={styles.userAvatar}>👤</div>
            <div>
              <div style={styles.userName}>{username}</div>
              <div style={styles.userRole}>{role}</div>
            </div>
          </div>

          <button onClick={handleLogout} style={styles.logoutBtn}>
            Déconnexion
          </button>
        </aside>
      )}

      {/* MAIN */}
      <main style={styles.main}>
        <header style={styles.topBar}>
          <button
            onClick={() => setSidebarOpen((v) => !v)}
            style={styles.menuBtn}
          >
            ☰
          </button>

          <div style={{ position: 'relative', width: 420 }}>
            <div style={styles.searchBar}>
              🔍
              <input
                aria-label="search"
                style={styles.searchInput}
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                placeholder="Rechercher un étudiant..."
              />
              {searchLoading && <span style={styles.loadingDot}>...</span>}
            </div>

            {showResults && (
              <div style={styles.dropdown}>
                {searchResults.length === 0 ? (
                  <div style={styles.empty}>
                    Aucun étudiant trouvé
                  </div>
                ) : (
                  searchResults.map((s, i) => (
                    <div
                      key={i}
                      style={styles.resultItem}
                      onClick={() => handleSelectStudent(s)}
                    >
                      <div style={{ fontWeight: 600 }}>
                        {s.name || 'Inconnu'}
                      </div>
                      <div style={{ fontSize: 12, color: COLORS.textMuted }}>
                        ID: {s.student_id || s.id || '-'}
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
        </header>

        <div style={styles.content}>
          {currentView === 'dashboard' && (
            <Dashboard addNotification={addNotification} />
          )}
          {currentView === 'enrollment' && (
            <Enrollment addNotification={addNotification} />
          )}
          {currentView === 'camera' && (
            <CameraRecognition addNotification={addNotification} />
          )}
        </div>
      </main>

      {/* TOASTS */}
      <div style={styles.toastContainer}>
        {notifications.map((n) => (
          <div
            key={n.id}
            style={{
              ...styles.toast,
              background:
                n.type === 'success'
                  ? COLORS.success
                  : n.type === 'error'
                  ? COLORS.error
                  : COLORS.info
            }}
          >
            {n.message}
          </div>
        ))}
      </div>
    </div>
  );
};

